quickRef.usagePattern:
// 页面入口（自动监听 ?action=stake → openStakeSosoDialog）
import StakingPage from '@/features/staking/pages/StakingPage';

// 主动打开 Stake SOSO 弹窗（详见 stake-soso feature）
import { openStakeSosoDialog } from '@/features/staking/components/StakeSosoDialog';
await openStakeSosoDialog({ rawAvailable, rawYourStaked });

// 由 stake-page 触发
import { openStakeSosoDialog } from '@/features/staking/components/StakeSosoDialog';

await openStakeSosoDialog({
  rawAvailable,    // useStakingBalancesQuery().rawAvailable
  rawYourStaked,   // useStakingBalancesQuery().rawYourStaked
});
